package demo.pharma.payment;
import demo.pharma.common.entity.BaseEntity; import demo.pharma.purchase.PurchaseOrder; import demo.pharma.supplier.Supplier; import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*;
@Entity @Table(name="purchase_invoices",indexes={@Index(name="idx_invoice_supplier",columnList="supplier_id"),@Index(name="idx_invoice_payment_status",columnList="payment_status")}) @Getter @Setter @NoArgsConstructor
public class PurchaseInvoice extends BaseEntity { @Column(nullable=false,unique=true,length=100) private String invoiceNumber; @Column(nullable=false) private LocalDate invoiceDate; @ManyToOne(optional=false) private Supplier supplier; @ManyToOne private PurchaseOrder purchaseOrder; @Column(nullable=false,precision=14,scale=2) private BigDecimal subtotal; @Column(nullable=false,precision=14,scale=2) private BigDecimal discount=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal tax=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal total; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus paymentStatus=PaymentStatus.UNPAID; }
